import{_ as t}from"./chunks/kataloge-floskeln-01.UgvR68IG.js";import{_ as s,o as a,c as u,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/grundlagen/zeugnisdruck-pruefen-leistungsdaten.png",o="/bilder/grundlagen/zeugnisdruck-gp-druck.png",d="/bilder/grundlagen/zeugnisdruck-druck-reportverwaltung.png",h="/bilder/grundlagen/zeugnisdruck-vorheriger-abschnitt.png",w=JSON.parse('{"title":"Zeugnisse vorbereiten, drucken und archivieren","description":"","frontmatter":{"title":"Zeugnisse vorbereiten, drucken und archivieren","source_pageid":561,"source_revision":7105},"headers":[],"relativePath":"einstieg/grundlagen/zeugnisvorbereitungen-und-zeugnisdruck-einfuehrung-in-schild-nrw.md","filePath":"einstieg/grundlagen/zeugnisvorbereitungen-und-zeugnisdruck-einfuehrung-in-schild-nrw.md"}'),g={name:"einstieg/grundlagen/zeugnisvorbereitungen-und-zeugnisdruck-einfuehrung-in-schild-nrw.md"};function c(m,i,p,b,k,f){return a(),u("div",null,[...i[0]||(i[0]=[r('<h1 id="zeugnisse-vorbereiten-drucken-und-archivieren" tabindex="-1">Zeugnisse vorbereiten, drucken und archivieren <a class="header-anchor" href="#zeugnisse-vorbereiten-drucken-und-archivieren" aria-label="Permalink to &quot;Zeugnisse vorbereiten, drucken und archivieren&quot;">​</a></h1><p>Planen Sie die Zeugnisphase von den Einstellungen und der Notenerfassung bis zu Konferenzen, Druck und Archivierung. Die einzelnen Aufgaben verweisen auf die zugehörigen Anleitungen.</p><h2 id="schulweite-vorgaben-vorbereiten" tabindex="-1">Schulweite Vorgaben vorbereiten <a class="header-anchor" href="#schulweite-vorgaben-vorbereiten" aria-label="Permalink to &quot;Schulweite Vorgaben vorbereiten&quot;">​</a></h2><h3 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h3><p>Grundsätzlich sind an einer Schule Rahmenbedingungen für die Eingabe von Noten und Fehlstunden zu klären.</p><p>Dies betrifft unter anderem:</p><ul><li>wie Fehlstunden in der SI und SII erfasst werden (als Gesamtsumme, fachbasiert kursweise oder aus tagesbezogenen Fehlstunden).</li><li>ob in der SI erweiterte Noten zugelassen sind (z.B. 1-, 3+ usw.)</li><li>wie mit nicht-gemahnten 5en und 6en verfahren wird.</li></ul><p>Weiterhin lässt sich die Noteneingabe sperren, damit nach dem Einlesen der Noten - oder sogar nach der Zeugniskonferenz! - keine unabgesprochenen Nachträge mehr vorgenommen werden können.</p><p>Diese Einstellungen finden Sie unter <em>Verwaltung ➜ Einstellungen ➜ Fächer, Noten</em> und der entsprechende Artikel im Wiki enthält weitere Informationen hierzu.</p><p>Ebenso sind die verwendeten Floskeln zu setzen und eventuell <a href="/zeugnisse/vorbereitung/abgeschlossene-faecher-holen-gruppenprozesse-noten-zeugnisvorbereitung.html">abgeschlossene Fächer</a> zu holen.</p><h3 id="floskeln" tabindex="-1">Floskeln <a class="header-anchor" href="#floskeln" aria-label="Permalink to &quot;Floskeln&quot;">​</a></h3><p><a href="/bilder/unterricht-kataloge/kataloge-floskeln-01.png"><img src="'+t+'" alt="Grundansicht der Floskelverwaltung unter Kataloge ➜ &quot;Floskeln&quot; bearbeiten." loading="lazy"></a></p><p><em>Grundansicht der Floskelverwaltung unter Kataloge ➜ &quot;Floskeln&quot; bearbeiten.</em></p><p>In SchILD-NRW gibt es sogenannte Floskeln. Dies sind wiederkehrende Bemerkungen, die in <em>Zeugnisbemerkungen</em>, <em>Bemerkungen zum Arbeits- und Sozialverhalten</em>, <em>Angaben zum außerunterrichtlichen Engagement</em> oder den <em>fachbezogenen Bemerkungen</em> vorkommen können.</p><p>Außerdem können Floskeln für <em>Textzeugnisse</em> angelegt werden.</p><p>Um diese Bemerkungen nicht immer eintippen zu müssen und damit einen gleichbleibenden Standard einzuhalten, können sie in SchILD-NRW mit einem Kürzel hinterlegt werden und so im Zeugnisdruck schnell per Mausklick eingefügt werden.</p><p>Der Artikel <a href="/schild3/unterricht-kataloge/floskeln-bearbeiten-schulbezogene-kataloge.html">Floskeln und Platzhalter verwalten</a> listet die zur Verwendung von Floskeln notwendigen Informationen auf.</p>',17),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Die endgültig zu verwendenden Floskeln beschließt die Schulkonferenz.")],-1),e("h2",{id:"die-zeugnisphase-in-schild",tabindex:"-1"},[n("Die Zeugnisphase in SchILD "),e("a",{class:"header-anchor",href:"#die-zeugnisphase-in-schild","aria-label":'Permalink to "Die Zeugnisphase in SchILD"'},"​")],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Führen Sie zu Beginn der Zeugnisphase ein Update auf die aktuellste Version von SchILD-NRW durch.")],-1),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die in diesem Artikel genannten "),e("em",null,"Vorlaufzeiten"),n(" sind als Vorschläge zum Nachdenken zu verstehen. Passen Sie bitte die Zeiträume an Ihre jeweils spezifische Situation an.")]),e("p",null,"Nehmen Sie bei der Planung Rücksicht auf mögliche Ausfallzeiten durch Feiertage, Ausflüge, Schulfeste, usw..")],-1),e("h3",{id:"gegebenenfalls-abfrage-an-schuler",tabindex:"-1"},[n("Gegebenenfalls Abfrage an Schüler "),e("a",{class:"header-anchor",href:"#gegebenenfalls-abfrage-an-schuler","aria-label":'Permalink to "Gegebenenfalls Abfrage an Schüler"'},"​")],-1),e("p",null,"Es kann sich empfehlen, ab und zu eine Abfrage an die Schüler (deren Erziehungsberechtigte) in Bezug auf ihre aktuellen Daten zu starten.",-1),e("p",null,"Eine solche Abfrage muss nicht in jedem Jahr stattfinden. Es sollte eine Abfrage rechtzeitig in Abschlussjahrgängen vorgenommen werden, um eventuelle Namensänderungen oder Änderungen der Konfession zu erfassen. Weiterhin sollte geklärt werden, ob die Konfession auf das Zeugnis gedruckt werden soll.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Lassen Sie auf jeden Fall ausreichend Zeit, um die notwendigen offiziellen Dokumente vorgezeigt bekommen zu können.")],-1),r('<p><strong>Vorlaufzeit</strong>: Monate bis Wochen vor dem Zeugnisdruck.</p><h3 id="uberprufung-der-angelegten-leistungsdaten" tabindex="-1">Überprüfung der angelegten Leistungsdaten <a class="header-anchor" href="#uberprufung-der-angelegten-leistungsdaten" aria-label="Permalink to &quot;Überprüfung der angelegten Leistungsdaten&quot;">​</a></h3><p><a href="/bilder/grundlagen/zeugnisdruck-pruefen-leistungsdaten.png"><img src="'+l+'" alt="Überprüfen der aktuellen Leistungsdaten vor dem Noteneintrag bzw. dem Export der Leistungsdaten." loading="lazy"></a></p><p><em>Überprüfen der aktuellen Leistungsdaten vor dem Noteneintrag bzw. dem Export der Leistungsdaten.</em></p><p>Damit Noten eingetragen werden können, müssen die <strong>Leistungsdaten</strong> des <strong>aktuellen Abschnitts</strong> korrekt sein.</p><p>Hat ein Schüler einen falschen Kurs oder einen tatsächlich besuchten Kurs nicht oder ist bei einem Fach aufgrund eines Wechsels eine falsche Lehrkraft eingetragen, erzeugen solche Fehler während und im Nachgang des Noteneintragens unnötige Nacharbeiten. Eventuell schlagen auch automatische Berechnungen von Abschlüssen oder der Versetzung fehl.</p>',6),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Bei Schülern der Oberstufe werden häufig Kurse abgewählt oder es verändert sich, ob ein Kurs "),e("em",null,"mündlich"),n(" oder "),e("em",null,"schriftlich"),n(" belegt wurde.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Überprüfen Sie in der Oberstufe immer kurz nach Beginn eines Abschnitts, ob alle Daten in SchILD-NRW, Lupo und einem eventuellen Stundenplanprogramm synchron und korrekt vorliegen. Nehmen Sie spätere Änderungen (z.B. Abwahlen oder Änderungen von "),e("em",null,"mündlich/schriftlich/der Abifächer 3 und 4"),n(" immer direkt nach der Beratung in allen drei Programmen vor.")])],-1),e("p",null,"Überprüfen Sie daher im Vorfeld, ob alle Kurse, Fächer, Lehrkräfte usw. korrekt sind.",-1),e("p",null,'Überprüfen Sie direkt bei dieser Gelegenheit, ob vorherige nicht gewertete Abschnitte bei Wiederholern auch als "nicht gewertet" markiert wurden.',-1),e("p",null,"Sollen auch Teilleistungen oder Prüfungsnoten (z.B. der ZP10) erfasst werden, müssen Teilleistungen und die Fächer bis zu diesem Moment entsprechend konfiguriert werden.",-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Wenn Leistungsdaten zum Noteneintrag exportiert wurden, zum Beispiel in Excel-Listen, dürfen die Leistungsdaten in SchILD-NRW nicht mehr verändert werden, da es sonst beim Import zu Fehlern kommen kann!")],-1),r('<p><strong>Vorlaufzeit</strong>: Einige Wochen zuvor, wenn relative Ruhe herrscht. Auf jeden Fall muss die Kontrolle vor dem Beginn der konkreten Noteneingabe/dem Notenexport abgeschlossen sein.</p><h3 id="noteneintragung" tabindex="-1">Noteneintragung <a class="header-anchor" href="#noteneintragung" aria-label="Permalink to &quot;Noteneintragung&quot;">​</a></h3><p>Tragen Sie nun die Noten ein. Hierzu gibt es diverse Wege:</p><ul><li>Sammeln der Leistungsdaten und Eintragung direkt in SchILD durch ausgewählte Personen</li><li>Zugriff von Lehrkräften direkt auf SchILD über einen eigenen Benutzernamen</li><li>Export der Leistungsdaten in Excel-Tabellen mit anschließendem Import</li><li>Notenerfassung mit <a href="/zeugnisse/noteneingabe.html">GradeHub und WeNoM</a> über den SVWS-Server; die Anleitungen stehen in der SVWS-Dokumentation</li><li>Eintragung über kostenpflichtige Weboberfläche SchILDWeb von Ribeka</li></ul><p>Je nach gewähltem Weg, können auch Bemerkungen (AuE wie &quot;Klassensprecherin&quot;), Prüfungsnoten oder Teilleistungen in Exportprogramme eingetragen werden.</p>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,"Beachten Sie die Möglichkeit, die Noteneingabe außerhalb eines gewünschten Fensters in SchILD zu sperren.")],-1),e("p",null,"Lassen Sie genug Zeit zum Eintragen der Noten. Je nachdem, wie Ihre Schule funktioniert, können einige Tage ausreichen, eventuell ist die Noteneintragung auch für zwei Wochen zu öffnen.",-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n('Achten Sie darauf, auch einen angemessenen Zeitraum zwischen dem "Ende der Noteneintragung" und dem "geplanten Beginn der Arbeit in den Abteilungen" zu lassen. Bei vielen Nachzüglern, Krankgeschriebenen usw. sind mitunter ca. zwei volle Werktage des Hinterherlaufens notwendig, um alle Noten auch tatsächlich im System vorliegen zu haben.'),e("br"),n(" Klären Sie die Zuständigkeiten, wer direkt nach dem Ende der Noteneintragung auf Vollständigkeit prüft.")]),e("p",null,"Kürzen Sie besser den Zeitraum des Noteneintragens um diese zwei Tage.")],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Der Gruppenprozess "),e("em",null,"Fächer, Noten"),n(" ➜ "),e("strong",null,"Fächer ohne Noten suchen"),n(" ist an dieser Stelle ein nützliches Werkzeug.")])],-1),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Um Listen von Nachzüglern mit Noten, Mahnungen und Fehlstunden kursweise einzupflegen beziehungsweise um als Abteilungsleitung/Koordination noch nicht gesetzte Mahnungen zu setzen, ist der Gruppenprozess "),e("em",null,"Noten, Mahnungen und Fehlstunden eingeben"),n(" sehr nützlich.")])],-1),r('<p>Beachten Sie bitte, dass ein Update auf SchILD-NRW, während mit einer anderen Version erstellte Notenlisten in Ihrem Haus unterwegs sind, beim Import dieser Dateien zu Fehlern führen kann. Warten Sie mit einem erneuten Update also bitte, bis die Leistungsdaten importiert wurden.</p><p><strong>Vorlaufzeit</strong>: Ca. zwei Wochen zur Noteneintragung und ca. zwei Werktage zur Kontrolle der Noteneingänge auf Vollständigkeit und eventuellem Hinterherlaufen und -telefonieren.</p><h3 id="teilleistungen-projektkursarbeiten" tabindex="-1">Teilleistungen, Projektkursarbeiten, ... <a class="header-anchor" href="#teilleistungen-projektkursarbeiten" aria-label="Permalink to &quot;Teilleistungen, Projektkursarbeiten, ...&quot;">​</a></h3><p>Erfassen Sie auch rechtzeitig je nach Notwendigkeit <a href="/schild3/schueler/teilleistungen-einrichten-und-verwalten-tutorial.html">Teilleistungen</a>, Lernbereichsnoten und Titel von Projektkursen und Themen von Projektkursarbeiten.</p><p>Beachten Sie hierzu die entsprechenden Artikel.</p><p><em>Lernbereichsnoten</em> werden im <em>Aktuellen Abschnitt</em> manuell oder über Gruppenprozesse eingegeben.</p><p>Die Themen von <em>Projektkursen</em> können unter Kurse bei der <em>Zeugnisbezeichnung</em> eingegeben werden. Bei der Anlage eines Projektkures ist unter den <em>Katalogen</em> das Fach mit dem Kürzel <em>PX</em> zu wählen und diese Projektkurs-Fächer müssen dann als <em>Fach der Oberstufe</em> markiert werden (das Kürzel <em>PX</em> ist Pseudofach und nicht für ASD).</p><p>Erfassen Sie das individuelle Thema einer Projektkursarbeit als <strong>Fachbezogene Bemerkung</strong>. Aktivieren Sie dafür unter <strong>Verwaltung → Einstellungen → Globale Einstellungen → Ansicht</strong> die fachbezogenen Bemerkungen. Doppelklicken Sie anschließend in den Leistungsdaten auf <strong>Fachbez. Leistungsentw.</strong>. Geben Sie dort die Bemerkung direkt ein oder wählen Sie eine Floskel.</p><p><strong>Vorlaufzeit</strong>: Zusätzliche Informationen wie Projektkursthemen usw. sollten bis einige Tage vor der Nachbearbeitung der eingegebenen Daten vorliegen und können im Zuge der Konferenzvorbereitung eingepflegt werden.</p><h3 id="zeugnisbemerkungen" tabindex="-1">Zeugnisbemerkungen <a class="header-anchor" href="#zeugnisbemerkungen" aria-label="Permalink to &quot;Zeugnisbemerkungen&quot;">​</a></h3><p>Geben Sie <em>Außerunterrichtliches Engagement</em> und eventuelle <em>Zeugnisbemerkungen</em> ein. Die Notenerfassung mit GradeHub und WeNoM ist dem SVWS-Server zugeordnet. Einrichtung und Bedienung sind in der <a href="https://doku.svws-nrw.de/" target="_blank" rel="noreferrer">SVWS-Dokumentation</a> beschrieben; siehe auch <a href="/zeugnisse/noteneingabe.html">Noten mit GradeHub und WeNoM erfassen</a>.</p><p>Einige Informationen liegen den Zeugnisbeauftragten nicht vor. Dies wären etwa Jahrgangssprecher oder wer in welcher Rolle in der Schülervertretung oder wer als Streitschlichter oder Schulsanitäter usw. mitwirkt.</p><p>Manche dieser Informationen können über AGen erfasst werden, andere müssen manuell zusammengetragen werden.</p><p><strong>Vorlaufzeit</strong>: Holen Sie rechtzeitig verteilte Informationen zusammen.</p><h3 id="fehlstundenberechnung" tabindex="-1">Fehlstundenberechnung <a class="header-anchor" href="#fehlstundenberechnung" aria-label="Permalink to &quot;Fehlstundenberechnung&quot;">​</a></h3><p>Wurden Fehlstunden nicht als Gesamt-Fehlstunden erfasst, sondern müssen aus <em>Tagesbezogenen</em> oder <em>Fachbezogenen</em> Fehlstunden gebildet werden, führen Sie den Gruppenprozess <em>Noten, Zeugnisvorbereit.</em> ➜ <strong>Fehlstundensummen autom. berechnen</strong> aus.</p>',16),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Wann immer nun im Nachgang Fehlstunden noch nachgetragen werden, z.B. aufgrund von eingereichten Papierlisten, muss dieser Gruppenprozess über der betroffenen Schülermenge erneut ausgeführt werden.")],-1),r('<p>Über den Gruppenprozess <em>Fehlstunden-Summen manuell eingeben</em> können die Summen klassenweise leicht nachgetragen werden.</p><h3 id="eingabe-von-konferenz-und-zeugnisdatum" tabindex="-1">Eingabe von Konferenz- und Zeugnisdatum <a class="header-anchor" href="#eingabe-von-konferenz-und-zeugnisdatum" aria-label="Permalink to &quot;Eingabe von Konferenz- und Zeugnisdatum&quot;">​</a></h3><p>Setzen Sie per Gruppenprozess das Konferenz- und Zeugnisdatum für den aktuellen Abschnitt.</p><p><strong>Vorlaufzeit</strong>: Im Rahmen der Konferenzvorbereitung.</p><h3 id="versetzungsberechnung" tabindex="-1">Versetzungsberechnung <a class="header-anchor" href="#versetzungsberechnung" aria-label="Permalink to &quot;Versetzungsberechnung&quot;">​</a></h3><p>Führen Sie den Gruppenprozess <em>Lernabschnitte, Versetzung</em> ➜ <strong>Versetzungs-/Abschlussberechnung</strong> durch, um basierend auf den Leistungsdaten und dem in SchILD-NRW hinterlegten Algorithmus diese Felder zu berechnen und zu befüllen.</p>',6),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Diese Werkzeuge dienen lediglich der Unterstützung ohne Gewähr. Die Prüfung auf Korrektheit der Ergebnisse im Rahmen der geltenden Rechtsgrundlagen obliegt immer den verantwortlichen Personen.")],-1),r(`<p>Wurden Veränderungen an den Leistungsdaten vorgenommen, ist die Prüfung erneut auszuführen. Diese kann über einen Gruppenprozess oder bei den individuellen Leistungsdaten des aktuellen Abschnitts (oben in der Kopfzeile des Fensters) angestoßen werden.</p><h3 id="berechnung-des-fhr-usw" tabindex="-1">Berechnung des FHR usw. <a class="header-anchor" href="#berechnung-des-fhr-usw" aria-label="Permalink to &quot;Berechnung des FHR usw.&quot;">​</a></h3><p>Liegen nun noch weitere Berechnungen, wie zum Beispiel für den <em>Schulischen Teil der Fachhochschulreife (FHR)</em> an, führen Sie diese wie in den entsprechenden Artikel beschrieben aus.</p><p>Achten Sie darauf, dass bei veränderten Leistungsdaten die Daten für den FHR neu geholt und dieser, beziehungsweise sein Schnitt, neu berechnet werden muss.</p><p>Sofern ein Abitur anliegt, sind die entsprechenden Berechnungen und Eingabe der Prüfungsleistungen wie in den Artikeln zum Abitur beschrieben durchzuführen.</p><h3 id="weitere-angaben-vor-der-konferenz" tabindex="-1">Weitere Angaben vor der Konferenz <a class="header-anchor" href="#weitere-angaben-vor-der-konferenz" aria-label="Permalink to &quot;Weitere Angaben vor der Konferenz&quot;">​</a></h3><h4 id="arbeitsgemeinschaften" tabindex="-1">Arbeitsgemeinschaften <a class="header-anchor" href="#arbeitsgemeinschaften" aria-label="Permalink to &quot;Arbeitsgemeinschaften&quot;">​</a></h4><p>Verarbeiten Sie nun Arbeitsgemeinschaften oder ähnlich. Diese können zum Beispiel über Kurse erfasst und auf einem Zeugnis ausgegeben werden.</p><p>Alternativ lassen sich passende Bemerkungen über Floskeln einfügen.</p><h4 id="schuler-die-nicht-automatisiert-verarbeitet-werden" tabindex="-1">Schüler, die nicht automatisiert verarbeitet werden <a class="header-anchor" href="#schuler-die-nicht-automatisiert-verarbeitet-werden" aria-label="Permalink to &quot;Schüler, die nicht automatisiert verarbeitet werden&quot;">​</a></h4><p>Kümmern Sie sich nun um Schüler, die nicht durch automatische Prozesse zu Versetzung und Abschlussberechnungen erfasst werden.</p><p>Dies sind möglicherweise einer Klasse zugeordnete <em>Flüchtlingskinder</em> oder Schüler, die <em>zieldifferenziert</em> unterrichtet werden und statt Zeugnissen individuelle Textzeugnisse oder andere Leistungsübersichten erhalten.</p><p>Verarbeiten Sie auch eventuell vorliegende <em>Anträge</em> von Erziehungsberechtigten.</p><h4 id="zuweisungen-o-a" tabindex="-1">Zuweisungen o.Ä. <a class="header-anchor" href="#zuweisungen-o-a" aria-label="Permalink to &quot;Zuweisungen o.Ä.&quot;">​</a></h4><p>Werden zum Beispiel Zuweisungen zu einer Differenzierungsebene an einer Gesamtschule vorgenommen, nehmen Sie diese soweit wie absehbar schon im Vorfeld der Konferenzen mit auf.</p><h2 id="vorbereitung-der-zeugnisreports" tabindex="-1">Vorbereitung der Zeugnisreports <a class="header-anchor" href="#vorbereitung-der-zeugnisreports" aria-label="Permalink to &quot;Vorbereitung der Zeugnisreports&quot;">​</a></h2><p>Auf der Webseite des <a href="https://www.svws.nrw.de" target="_blank" rel="noreferrer">MSB für Schulverwaltungssoftware</a> finden sich aktuelle Zeugnisformulare, die für den aktuellen Abschnitt genutzt werden sollen.</p><p>Unter <strong><a href="/reporting/zeugnisformulare/zeugnisse-themenuebersicht.html">Den Zeugnisdruck vorbereiten</a></strong> finden sich die hierzu notwendigen Informationen.</p><p>Eventuelle Veränderungen der Zeugnisse sind an dieser Stelle ebenfalls vorzunehmen. Soll zum Beispiel ein Stadtwappen oder ein anderes Logo des Schulträgers, das nicht das in der Datenbank hinterlegte Schul-Logo ist, auf dem Zeugnis auftauchen, muss dieses in die Reports eingebaut werden.</p><p>Es empfiehlt sich, im Reportverzeichnis eine Ordnerstruktur anzulegen, in dem die Zeugnisse nach Abschnitt sortiert werden und somit auch für rückwirkende Nachdrucke mit den Originalreports zur Verfügung stehen.</p><p>Beispiel für das 1. Halbjahr vom Schuljahr 2023/24:</p><pre><code> C:\\SVWS-Arbeitsverzeichnis\\Schild-Reports\\Zeugnisse\\2023_24_1
</code></pre><p>Es kann sich noch eine Differenzierung gegebenenfalls in z.B. &#39;SI&#39; und &#39;SII&#39; anschließen.</p><p>Beachten Sie ebenfalls, dass <a href="/zeugnisse/vorbereitung/zeugnisvorlagen-zuordnen-schulbezogene-kataloge.html">Zeugnisvorlagen zugeordnet</a> werden können. Sollen Zeugnisse mit zugeordneten Vorlagen gedruckt werden, würde dies in diesem Schritt konfiguriert werden. Der Druck findet dann über den Gruppenprozess <a href="/zeugnisse/vorbereitung/zugeordnete-zeugnisformulare-drucken-gruppenprozesse-noten-zeugnisvorbereitung.html">Zugeordnete Zeugnisvorlagen drucken</a> statt.</p>`,24),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,"Bereiten Sie die Formulare nicht zu früh vor, mitunter werden zeitnah noch neue Versionen mit Fehlerbehebungen oder Verbesserungen veröffentlicht.")],-1),r('<p><strong>Vorlaufzeit</strong>: Je nach persönlichem Komfortgefühl einige Tage bis eine Stunde vor dem Zeugnisdruck.</p><h2 id="konferenzen" tabindex="-1">Konferenzen <a class="header-anchor" href="#konferenzen" aria-label="Permalink to &quot;Konferenzen&quot;">​</a></h2><p>Laden Sie fristgerecht und entsprechend des gültigen Rechtsrahmens zu Zeugniskonferenzen und führen Sie diese durch.</p><p>Pflegen Sie die sich aufgrund von Konferenzbeschlüssen ergebenden Änderungen ein. Dies ist mitunter auch direkt von der Konferenz aus möglich, wenn eine Netzwerkverbindung zu SchILD-NRW besteht.</p><p>Leistungsübersichten können als Report erzeugt werden, um sie als .pdf anzuzeigen.</p><p>Es kann auch ein Konferenzmodul verwendet werden, um Änderungen auch direkt einzugeben und anzuzeigen.</p><h2 id="zeugnisdruck-und-archivierung" tabindex="-1">Zeugnisdruck und Archivierung <a class="header-anchor" href="#zeugnisdruck-und-archivierung" aria-label="Permalink to &quot;Zeugnisdruck und Archivierung&quot;">​</a></h2><p>Es gibt nun zwei Möglichkeiten, die Zeugnisse zu drucken.</p><p><a href="/bilder/grundlagen/zeugnisdruck-gp-druck.png"><img src="'+o+'" alt="Druck über den Gruppenprozess Zugeordnete Zeugnisformulare drucken." loading="lazy"></a></p><p><em>Druck über den Gruppenprozess Zugeordnete Zeugnisformulare drucken.</em></p><p>Zum einen kann über die Gruppenprozess <em>Noten, Zeugnisvorbereitung</em> ➜ <strong>Zugeordnete Zeugnisformulare drucken</strong> gedruckt werden.</p><p>Wurden Zeugnisformulare zugeordnet, kann der Druck hier komfortabel angestoßen werden. Wählen Sie erst die zu druckenden Zeugnisse aus und klicken auf <strong>Ausgabe starten</strong>.</p><p>Dann muss angewählt sein, dass <strong>die ganze Gruppe</strong> gedruckt werden soll.</p><p>Anschließend wählen Sie im üblichen Druckmenü die Art der Ausgabe.</p><ul><li><strong>Vorschau</strong>, um einen Blick auf das fertige Ergebnis zu werfen</li><li><strong>Drucker mit Archivierung</strong> um die Zeugnisse erst zu einem Drucker zu senden und dann anschließend einen zweiten Satz zu generieren, der in der Dokumentenablage abgelegt wird, sofern diese aktiviert wurde.</li><li><strong>Drucker ohne Archivierung</strong> schickt die Zeugnisse zu einem Drucker, ohne dass eine Kopie in der Dokumentenablage erzeugt wird.</li><li><strong>nur Archivierung</strong> erzeugt die Zeugnisse in der Dokumentenablage, ohne den Dialog für einen physischen Druck zu öffnen.</li><li><strong>Archivierung in Zeugnisverzeichnis</strong> funktioniert wie die Dokumentenablage, jedoch werden die .pdf-Dateien im konfigurierten Zeugnisverzeichnis abgelegt.</li></ul><p>Bestätigen Sie mit <strong>OK</strong> und warten Sie bitte unbedingt ab, bis der Gruppenprozess abgeschlossen ist, bevor Sie einen neuen anstoßen.</p><p><a href="/bilder/grundlagen/zeugnisdruck-druck-reportverwaltung.png"><img src="'+d+'" alt="Wahl des gewünschten Reports für eine gefilterte Schülermenge." loading="lazy"></a></p><p><em>Wahl des gewünschten Reports für eine gefilterte Schülermenge.</em></p><p>Weiterhin kann auch über die <strong>Reportverwaltung</strong> gedruckt werden. Hierbei filtern Sie die zu druckende Schülergruppe im Schülercontainer und starten dann den Druck des gewünschten Reports.</p><p>Auch hier stehen die oben besprochenen Wahlmöglichkeiten zu Druck und Archivierung zur Verfügung.</p><p>Ist dies gewünscht, drucken beziehungsweise kopieren Sie an dieser Stelle eventuelle, den Vorgaben entsprechende Exemplare für eine physische Archivierung.</p>',21),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Konsultieren Sie die "),e("em",null,"VO-DV I"),n(" und die genannten Löschfristen, um zu entscheiden, ob und welche Zeugnisse in welcher Form zu archivieren sind.")])],-1),r('<h3 id="uberweisungszeugnisse-abgangs-und-abschlusszeugnisse" tabindex="-1">Überweisungszeugnisse, Abgangs- und Abschlusszeugnisse <a class="header-anchor" href="#uberweisungszeugnisse-abgangs-und-abschlusszeugnisse" aria-label="Permalink to &quot;Überweisungszeugnisse, Abgangs- und Abschlusszeugnisse&quot;">​</a></h3><p><a href="/bilder/grundlagen/zeugnisdruck-vorheriger-abschnitt.png"><img src="'+h+'" alt="Fand mittlerweile ein Abschnittswechsel statt, ist daran zu denken, ein Abgangszeugnis mit dem vorherigen Abschnitt als Datenbasis zu drucken." loading="lazy"></a></p><p><em>Fand mittlerweile ein Abschnittswechsel statt, ist daran zu denken, ein Abgangszeugnis mit dem vorherigen Abschnitt als Datenbasis zu drucken.</em></p><p>Verlässt ein Schüler mit einem ausgegebenen Zeugnis die Schule, ist der Prozess wie oben durchzuführen. Jedoch sind darüber hinaus zuvor noch weitere Vorbereitungen zu treffen:</p><ul><li><strong>Sprachreferenzniveau eintragen:</strong> Prüfen Sie zuerst die Sprachenfolge. Unter <strong>Gruppenprozesse → Allgemein</strong> kann <strong>Sprachenfolge aus Leistungsdaten ermitteln</strong> die vorhandenen Leistungsdaten auswerten. <strong>Sprach-Referenzniveau ermitteln</strong> berechnet daraus das Niveau, soweit dies möglich ist. Ein erreichtes Latinum, Graecum oder Hebraicum tragen Sie weiterhin von Hand ein; diese Angaben werden nicht automatisch gesetzt.</li><li>Setzen Sie unter <em>Schüler</em> im Reiter <em>Schulbesuch</em> das Entlassdatum <strong>Entlassen am...</strong>. Dieses ist mindestens zu setzen, füllen Sie aber bitte auch die anderen Felder korrekt aus. Wird der Gruppenprozess <strong>Zeugnisse drucken und Schüler ausschulen</strong> genutzt, ist dieser Schritt nicht notwendig.</li></ul>',5),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Falls mittlerweile ein Abschnittswechsel stattfand, ist in der "),e("em",null,"Reportverwaltung"),n(" der vorherige Abschnitt als Datenbasis für den Zeugnisdruck einzustellen.")]),e("p",null,"Eventuell ist beim Schüler auch ein schon angelegter, aber tatsächlich nie besuchter aktueller Abschnitt zu entfernen.")],-1),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,"Ein Schüler der EF entscheidet sich doch, nach dem 1. Halbjahr zu gehen und bekommt ein Abgangszeugnis für dieses Halbjahr ausgestellt, obwohl die Schule schon ins 2. Halbjahr übertragen wurde.")],-1),r('<h2 id="text-und-ankreuzzeugnisse" tabindex="-1">Text- und Ankreuzzeugnisse <a class="header-anchor" href="#text-und-ankreuzzeugnisse" aria-label="Permalink to &quot;Text- und Ankreuzzeugnisse&quot;">​</a></h2><p>Über SchILD-NRW lassen sich <em>Text-</em> und <em>Ankreuzzeugnisse</em> generieren. Ebenfalls können <em>Lernstandsberichte</em> erzeugt werden, die ähnlich wie Textzeugnisse funktionieren.</p><p>Die Zeugnisse sind über die Seite des MSB für Schulverwaltungssoftware wie alle anderen Zeugnisse auch zu beziehen. Sie finden sich im Bereich für die Grundschule.</p><p>Erzeugen Sie für <em>Textzeugnisse</em> erst die gewünschten Floskeln über <em>Kataloge ➜ &quot;Floskeln&quot; bearbeiten</em>.</p><p>Entsprechend werden die Ankreuzkompetenzen unter <em>Kataloge ➜ Angaben für Ankreuzzeugnisse</em> hinterlegt.</p><p>Ausführliche Anleitungen zu diesen Zeugnisformen finden Sie unter <a href="/zeugnisse/grundschule.html">Zeugnisse und Lernstandsberichte der Grundschule erstellen</a>.</p><h2 id="haufige-fehler-beim-zeugnisdruck" tabindex="-1">Häufige Fehler beim Zeugnisdruck <a class="header-anchor" href="#haufige-fehler-beim-zeugnisdruck" aria-label="Permalink to &quot;Häufige Fehler beim Zeugnisdruck&quot;">​</a></h2>',7),e("div",{"data-hint-kind":"tip",class:"tip custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"tip","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 18h6m-5 3h4m-5-6c-4-3-4-9 0-11 5-3 11 1 9 6-.5 2-2 3-3 5v1H9z"})]),n("Tipp")]),e("p",null,[n("Nehmen Sie das Tutorial zu den "),e("em",null,"Häufigen Fehlern beim Zeugnisdruck"),n(" zur Kenntnis.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zeugnisvorbereitungen_und_Zeugnisdruck_(Einf%C3%BChrung_in_SchILD-NRW)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 7105.")],-1)])])}const S=s(g,[["render",c]]);export{w as __pageData,S as default};
